-- Idempotently preserve the first batch of supplemental study outlines for
-- MBH histology exam prompts. These are generated study aids, not verbatim source
-- answers; they remain clearly labelled as supplements in the answer text.
with supplemental_answers(id, answer) as (
  values
  ('caf272f2-6191-57ba-acf3-71f48911d4ae', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Тромбоциты — безъядерные фрагменты цитоплазмы мегакариоцитов, участвующие в первичном гемостазе и запуске коагуляции. В мазке видны мелкие пластинки с более тёмной центральной грануломерой и светлой периферической гиаломерой. Они адгезируют к повреждённой сосудистой стенке, активируются, агрегируют и выделяют содержимое гранул. Количество и референсные пределы зависят от лаборатории; в ответе по гистологии главное — происхождение, строение и роль в остановке кровотечения.'),
  ('9eae246f-cf70-5716-b62c-5c3ac21776d3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нейтрофилы — наиболее многочисленные гранулоциты, имеют сегментированное ядро и фагоцитируют микроорганизмы; эозинофилы обладают крупными эозинофильными гранулами и участвуют в противопаразитарной защите и аллергическом воспалении; базофилы содержат гранулы с медиаторами, включая гистамин и гепарин. При описании укажите форму ядра, окраску гранул и функцию. Лейкоцитарная формула — относительная доля типов лейкоцитов; нормы зависят от возраста и лабораторного диапазона.'),
  ('46965ca8-3f17-52b6-b785-cf3030e2fb12', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Форменные элементы крови — эритроциты, лейкоциты и тромбоциты. Лейкоциты делятся на гранулоциты и агранулоциты. Агранулоциты: лимфоциты (T-, B-, NK-популяции) и моноциты. Лимфоциты имеют крупное округлое ядро и узкий ободок цитоплазмы; моноциты крупнее, с бобовидным ядром и серо-голубой цитоплазмой. Лейкоцитарная формула показывает относительное содержание пяти основных типов лейкоцитов; абсолютные показатели важны для клинической интерпретации. T-лимфоциты участвуют в клеточном иммунитете, B-лимфоциты обеспечивают гуморальный ответ через плазмоциты.'),
  ('b589b5cb-44f0-52bd-ac0c-d684562b59b3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гранулоциты включают нейтрофилы, эозинофилы и базофилы. Нейтрофилы имеют сегментированное ядро и мелкую нейтрофильную зернистость; фагоцитируют бактерии и участвуют в остром воспалении. Эозинофилы имеют обычно двудольчатое ядро и крупные эозинофильные гранулы; участвуют в противопаразитарной защите и регуляции аллергии. Базофилы содержат крупные базофильные гранулы с медиаторами воспаления и участвуют в реакциях гиперчувствительности. Лейкоцитарная формула — процентное соотношение лейкоцитов; референсные значения зависят от возраста и лаборатории.'),
  ('8ff123d9-c94d-5b58-b7ab-7d245ab896e8', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Лейкоциты делятся на гранулоциты (нейтрофилы, эозинофилы, базофилы) и агранулоциты (лимфоциты, моноциты). Лимфоциты: T-клетки обеспечивают клеточный иммунитет и регулируют ответ; B-клетки дают начало плазмоцитам и клеткам памяти; NK-клетки уничтожают некоторые инфицированные и опухолевые клетки. Моноциты — крупные клетки с бобовидным ядром; в тканях могут дифференцироваться в макрофаги. Лейкоцитарная формула показывает относительную долю каждого вида; её интерпретируют вместе с абсолютным числом клеток.'),
  ('fd686227-01ed-5909-ac64-079d2e357dcb', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Агранулоциты — лимфоциты и моноциты; в их цитоплазме нет специфической зернистости, различимой обычной световой микроскопией. Лимфоциты имеют плотное округлое ядро и узкий ободок цитоплазмы; T-клетки обеспечивают клеточный иммунитет, B-клетки дифференцируются в плазматические клетки и клетки памяти, NK-клетки участвуют в цитотоксической защите. Плазмоциты имеют эксцентричное ядро с грубым хроматином и развитую гранулярную ЭПС для синтеза антител. Лейкоцитарная формула отражает процентное соотношение разных лейкоцитов в крови.'),
  ('270b0c00-ecd4-5393-9d70-4c0f09a3ff98', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Железы развиваются из эпителия, который врастает в подлежащую ткань; экзокринные сохраняют связь с поверхностью через выводной проток, эндокринные выделяют гормоны в кровь и протоков не имеют. По числу клеток различают одноклеточные и многоклеточные; многоклеточные — простые/сложные, трубчатые/альвеолярные (ацинарные) и смешанные по форме отделов. Секреторные клетки синтезируют и выделяют белковый, слизистый или смешанный секрет. При ответе укажите источник развития, тип секреции, устройство концевых отделов и протоков.'),
  ('3a6010ab-2365-578d-881e-327342153ba3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Костная ткань бывает грубоволокнистой и пластинчатой; пластинчатая формирует компактное и губчатое вещество. Остеобласты синтезируют остеоид, остеоциты поддерживают матрикс, остеокласты резорбируют его. Органическая часть матрикса включает коллаген I типа и неколлагеновые белки; неорганическая — преимущественно кальций-фосфатные минералы. С возрастом меняются скорость ремоделирования и баланс образования/резорбции; при недостатке минералов и белка снижается прочность, а гормональные изменения влияют на костную массу.'),
  ('a032e282-b30e-529a-b038-0154a4534268', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Диафиз трубчатой кости окружён надкостницей; под ней располагаются наружные общие пластинки, затем остеоны компактного вещества, внутренние общие пластинки и эндост. Остеон состоит из концентрических костных пластинок вокруг центрального канала с сосудами и нервами; каналы соединяются перфоративными каналами. Питание поступает из сосудов надкостницы и костномозговой полости через сосудистые каналы. Ремоделирование обеспечивают остеокласты и остеобласты; рост в длину происходит в эпифизарной пластинке до её закрытия, рост в толщину — за счёт надкостницы.'),
  ('c70f750d-d549-5267-a084-e49e6ef6e184', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эндохондральный остеогенез происходит на месте модели гиалинового хряща. Хрящ кальцифицируется, хондроциты гипертрофируются и гибнут; сосуды и клетки-предшественники проникают в область костной манжетки, остеокласты/хондрокласты удаляют матрикс, а остеобласты откладывают костный матрикс на остатках хрящевых перегородок. Формируются первичный центр окостенения в диафизе и вторичные центры в эпифизах; до закрытия эпифизарной пластинки рост кости в длину сохраняется. Рост и ремоделирование зависят от нагрузки, питания (кальций, фосфаты, белок, витамины D и C), гормонов и возраста.'),
  ('b2b72a53-3b81-5d76-ad93-ecac7b459643', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гладкая мышечная ткань чаще развивается из мезенхимы и входит в стенки сосудов и полых органов. Гладкий миоцит — веретеновидная одноядерная клетка без поперечной исчерченности; актиновые и миозиновые филаменты закреплены на плотных тельцах. Сокращение регулируется Ca2+ и кальмодулином с активацией киназы лёгких цепей миозина, а не тропонином. Питание обеспечивается диффузией из капилляров; иннервация преимущественно вегетативная, передача сигнала часто осуществляется через варикозные утолщения аксонов. Клетки способны к гипертрофии и в определённых условиях к пролиферации.'),
  ('7363613d-1921-5cd4-819f-2c06b77c8ff9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпителий почечных канальцев формируется из эпителия нефрогенной ткани, происходящей из промежуточной мезодермы. Кубические клетки канальцев имеют полярность; у проксимального отдела выражена щёточная каёмка и много митохондрий, что соответствует интенсивной реабсорбции. Мезотелий — однослойный плоский эпителий серозных оболочек, развивается из мезодермы боковой пластинки (латеральной пластинки мезодермы) и обеспечивает гладкую поверхность для скольжения органов. В препарате различайте расположение, форму клеток и характер подлежащей соединительной ткани.'),
  ('9f2c474e-4aa8-56b7-b2e0-76662c645776', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Различают грубоволокнистую (ретикулофиброзную) и пластинчатую костную ткань; в зрелой кости пластинки организованы в остеоны и межуточные системы. Матрикс содержит органическую часть (преимущественно коллаген I типа и белки основного вещества) и неорганические соли, главным образом кристаллы гидроксиапатита. Коллаген обеспечивает сопротивление растяжению, минералы — твёрдость и сопротивление сжатию. Костные клетки: остеобласты, остеоциты и остеокласты.'),
  ('f15deb4c-6038-5afe-8272-0f4a8280583a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Остеобласты происходят из мезенхимных остеогенных клеток, синтезируют органический матрикс и регулируют его минерализацию; клетки, замурованные в матриксе, становятся остеоцитами. Остеоциты поддерживают матрикс и воспринимают механическую нагрузку. Остеокласты — крупные многоядерные клетки моноцитарно-макрофагального происхождения, резорбирующие кость в лакунах резорбции. Клетки остеогенного ряда надкостницы и эндоста участвуют в росте и восстановлении кости.'),
  ('6c51a3dd-a539-5812-ab64-d295537ce49b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Диафиз трубчатой кости покрыт надкостницей с наружным фиброзным и внутренним остеогенным слоями; изнутри костномозговая полость выстлана эндостом. Компактное вещество организовано в остеоны с центральными каналами, между ними находятся вставочные пластинки. Рост в длину идёт в эпифизарной пластинке за счёт пролиферации и последующего замещения хряща костью; рост в толщину обеспечивается аппозиционным отложением кости остеобластами надкостницы. Физиологическое ремоделирование согласует резорбцию остеокластами и образование матрикса остеобластами.'),
  ('2e564bb4-43ea-5544-b8a2-43a969dfe5c3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гладкая мышечная ткань мезенхимного происхождения входит в стенки сосудов, кишечника, мочевых путей и матки. Клетки веретеновидные, с одним центральным ядром; в цитоплазме — актин, миозин, промежуточные филаменты и плотные тельца. Ca2+ связывается с кальмодулином, комплекс активирует киназу лёгких цепей миозина и запускает взаимодействие актин-миозин. Вегетативные аксоны образуют варикозные расширения; медиатор диффундирует к нескольким клеткам, поэтому ответ может быть координированным. Возбудимость зависит также от растяжения, гормонов и местных факторов.'),
  ('d554774c-0643-5860-bf23-ad7ce7883ac0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Основная масса гладкой мышечной ткани имеет мезенхимное происхождение; миоэпителиальные клетки желез связаны с эпителиальным (эктодермальным) происхождением, а мышцы радужки развиваются из нейроэктодермы. Гладкие миоциты не имеют саркомеров, сокращаются медленно и экономно, могут поддерживать тонус. В стенках сосудов и внутренних органов их работа регулируется вегетативной нервной системой, гормонами, локальными медиаторами и растяжением. Необходимо отличать гладкие миоциты от миоэпителиальных клеток по расположению и функции.'),
  ('f5f3b8ba-3e13-56fc-aae4-10b912272b2e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Секреторный цикл включает поступление исходных веществ, синтез секрета, накопление/созревание, выделение и восстановление клетки. Белковые секреты обычно синтезируются на гранулярной ЭПС и обрабатываются в комплексе Гольджи; липидные — преимущественно в гладкой ЭПС. Мерокриновая секреция идёт экзоцитозом без потери цитоплазмы; апокриновая сопровождается отделением апикальной части клетки; голокриновая — гибелью и распадом клетки. Железы классифицируют по числу клеток, строению выводных протоков и секреторных отделов, характеру секрета и способу секреции.'),
  ('be0e5b0a-83cf-5527-9beb-987f85536a47', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Прямой (десмальный) остеогенез начинается в мезенхиме без хрящевой модели. Мезенхимные клетки дифференцируются в остеобласты, которые синтезируют остеоид (коллаген I типа и основное вещество); после минерализации часть остеобластов становится остеоцитами в лакунах. Формируются костные трабекулы, между ними сохраняется сосудистая мезенхима; затем развивается пластинчатая кость и надкостница. Такой механизм характерен для многих плоских костей черепа и части ключицы.'),
  ('b7a792b9-b4d5-5548-ba1d-573ecf79c022', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Волокнистая соединительная ткань состоит из клеток и внеклеточного матрикса — волокон и основного аморфного вещества; развивается преимущественно из мезенхимы. Различают рыхлую и плотную ткань; плотная бывает оформленной (параллельные пучки, например сухожилие) и неоформленной (пучки в разных направлениях, например дерма). В рыхлой ткани встречаются фибробласты/фиброциты, макрофаги, тучные клетки, плазмоциты, лейкоциты и адипоциты; волокна представлены коллагеновыми, эластическими и ретикулярными. Функции: опорная, трофическая, защитная, репаративная.')
)
update public.exam_questions q
set answer = s.answer,
    updated_at = now()
from supplemental_answers s
where q.id = s.id
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
